<script lang="ts">
 import { api, type Grant } from './api'; import {canEdit} from './findings'; import {dataUrl,nextSort,expiryError} from './data-pages'; import { Button, DataTable, EmptyState, ErrorState, Input, Pagination, Panel, Pill, Skeleton, Tabs } from './ui';
 let {realms,grants}:{realms:string[],grants:Grant[]}=$props();
 type Oath={id:number,advisory_id:string,name_key:string,service_name:string,realm:string|null,kind:string,reason:string,status:string,expires_at:string|null,review_at:string|null};
 let rows=$state<Oath[]>([]),tab=$state('active'),offset=$state(0),sort=$state('date'),order=$state('asc'),loading=$state(true),failed=$state(false),revision=$state(0), action=$state<'extend'|'revoke'|null>(null), target=$state<Oath|null>(null),until=$state(''),error=$state(''),busy=$state(false);
 let url=$derived(dataUrl('/api/v1/ui/oaths',realms,offset,sort,order,{tab}));
 $effect(()=>{realms.join(',');offset=0;target=null;action=null;});
 $effect(()=>{const targetUrl=url;revision;let active=true;loading=true;failed=false;api<Oath[]>(targetUrl).then(data=>{if(active){rows=data;loading=false;}}).catch(()=>{if(active){failed=true;loading=false;}});return ()=>{active=false};});
 function chooseTab(value:string){tab=value;offset=0;target=null;action=null;}
 function changeSort(field:string){[sort,order]=nextSort(sort,order,field);offset=0;} function sortState(field:string):'ascending'|'descending'|'none'{return sort===field?(order==='asc'?'ascending':'descending'):'none';}
 function start(row:Oath, operation:'extend'|'revoke'){target=row;action=operation;until='';error='';}
 async function confirm(){if(!target||!action)return;if(action==='extend' && (error=expiryError(until)))return;busy=true;error='';try{await api(`/api/v1/oaths/${target.id}/${action}`,{method:'POST',...(action==='extend'?{headers:{'Content-Type':'application/json'},body:JSON.stringify({until})}:{})});target=null;action=null;revision++;}catch{error='Could not update this oath. Please try again.';}finally{busy=false;}}
</script>
<div class="page">
<Tabs label="Oath status" current={tab} change={chooseTab} items={[{id:'active',label:'Active'},{id:'expiring',label:'Expiring within 7 days'},{id:'past',label:'Expired / revoked'}]} />
<Panel flush>
{#if loading}<Skeleton/>{:else if failed}<ErrorState retry={()=>revision++}/>{:else if !rows.length}<EmptyState title={tab==='active'?'No oaths sworn':'No oaths in this view'} body={tab==='active'?'Every open finding still counts and still alerts. Open a finding and choose Take an oath to snooze it until a date, or ignore it with a reason.':'Nothing here yet.'}/>{:else}<DataTable label="Oaths"><thead><tr>{#each [['advisory','Finding'],['service','Service'],['realm','Realm'],['kind','Decision'],['date','Expires / review'],['status','Status']] as [field,label]}<th aria-sort={sortState(field)}><button onclick={()=>changeSort(field)}>{label}</button></th>{/each}<th>Reason</th><th><span class="sr">Actions</span></th></tr></thead><tbody>{#each rows as row}{@const due=row.expires_at ?? row.review_at}<tr><td><span class="mono">{row.advisory_id}</span><br/><span class="mono muted">{row.name_key}</span></td><td>{row.service_name}</td><td>{row.realm ?? 'All realms'}</td><td><Pill tone={row.kind==='ignore'?'neutral':'gold'}>{row.kind}</Pill></td><td>{due?.slice(0,10) ?? '—'}</td><td>{row.status==='active' && due && new Date(due).getTime()<=Date.now() ? 'expired' : row.status}</td><td>{row.reason}</td><td>{#if canEdit(grants,row.realm ?? '*') && row.status!=='revoked'}<div class="actions"><Button size="sm" onclick={()=>start(row,'extend')}>Extend</Button><Button size="sm" variant="danger" onclick={()=>start(row,'revoke')}>Revoke</Button></div>{:else}<span class="muted">—</span>{/if}</td></tr>{/each}</tbody></DataTable>{/if}
{#if !failed}<Pagination {offset} count={rows.length} {loading} change={(n)=>offset=n}/>{/if}
</Panel>
{#if target && action}<Panel title={`${action==='extend'?'Extend':'Revoke'} oath for ${target.advisory_id}?`}><div class="confirm"><p class="muted">{target.service_name} · {target.realm ?? 'All realms'}</p>{#if action==='extend'}<Input label="New expiry / review date" type="date" bind:value={until}/>{:else}<p>This removes the oath’s protection for this finding.</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="actions"><Button variant={action==='revoke'?'danger':'primary'} disabled={busy} onclick={confirm}>Confirm {action}</Button><Button variant="ghost" disabled={busy} onclick={()=>{target=null;action=null;}}>Cancel</Button></div></div></Panel>{/if}
</div>
<style>.page{display:grid;gap:var(--s3)}.actions{display:flex;gap:var(--s2);flex-wrap:wrap}.mono{font-family:var(--font-mono);font-size:var(--text-sm);overflow-wrap:anywhere}.muted{color:var(--muted)}.confirm{display:grid;gap:var(--s3);max-width:420px}.confirm p{margin:0}.error{color:var(--sev-high);margin:0}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}</style>
